#include "../common.h"
int main(void){int p[2][2],c[2][2],det,iv;puts("Enter two plaintext digraphs as numeric A=0..Z=25 (rows):");for(int i=0;i<2;i++)scanf("%d%d",&p[i][0],&p[i][1]);puts("Enter matching ciphertext digraphs (rows):");for(int i=0;i<2;i++)scanf("%d%d",&c[i][0],&c[i][1]);det=modn(p[0][0]*p[1][1]-p[0][1]*p[1][0],26);iv=invn(det,26);if(iv<0){puts("Plaintext matrix is not invertible mod 26; choose different pairs.");return 1;}int x=modn(p[1][1]*iv,26),y=modn(-p[0][1]*iv,26),z=modn(-p[1][0]*iv,26),w=modn(p[0][0]*iv,26);printf("Recovered key: [%d %d; %d %d]\n",modn(c[0][0]*x+c[1][0]*y,26),modn(c[0][0]*z+c[1][0]*w,26),modn(c[0][1]*x+c[1][1]*y,26),modn(c[0][1]*z+c[1][1]*w,26));}
